-- APENAS NO PROJETO "Solar Clean testes crm". NUNCA executar em produção.
-- Esquema derivado da lista de colunas fornecida pelo usuário em 28/10/2026.
-- Não copia nem exclui registros. Não concede acesso anon.
-- O id foi reportado como bigint sem default; em homologação usamos
-- GENERATED BY DEFAULT AS IDENTITY para permitir INSERTs do aplicativo.
CREATE TABLE IF NOT EXISTS public.vistorias (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 client_uuid uuid NOT NULL UNIQUE,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 cliente text,
 telefone text,
 cidade text,
 endereco text,
 placas integer,
 pot_placa numeric,
 marca_placa text,
 marca_inv text,
 modelo_inv text,
 ano_inst text,
 telhado text,
 sujeira text,
 sujidades jsonb DEFAULT '[]'::jsonb,
 estrutura text,
 dps text,
 qtd_dps text,
 modelo_dps text,
 inv_status text,
 erro_inv text,
 antes numeric,
 depois numeric,
 limpeza text,
 retorno text,
 obs text,
 pct numeric,
 tecnico text,
 tecnico_email text,
 show_generation boolean NOT NULL DEFAULT true,
 media_manifest jsonb NOT NULL DEFAULT '[]'::jsonb,
 client_signature text,
 signature_at timestamptz,
 tech_signature text,
 inv_internet text NOT NULL DEFAULT 'Não verificado',
 pagamento_status text DEFAULT 'Pendente',
 pagamento_forma text,
 valor_cobrado numeric DEFAULT 0,
 valor_recebido numeric DEFAULT 0
);
ALTER TABLE public.vistorias ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.vistorias FROM anon;
REVOKE ALL ON public.vistorias FROM authenticated;
GRANT SELECT, INSERT, UPDATE ON public.vistorias TO authenticated;
GRANT USAGE ON SCHEMA public TO authenticated;
GRANT USAGE, SELECT ON SEQUENCE public.vistorias_id_seq TO authenticated;

DROP POLICY IF EXISTS vistoria_teste_select ON public.vistorias;
DROP POLICY IF EXISTS vistoria_teste_insert ON public.vistorias;
DROP POLICY IF EXISTS vistoria_teste_update ON public.vistorias;
CREATE POLICY vistoria_teste_select ON public.vistorias
 FOR SELECT TO authenticated USING (
   EXISTS (SELECT 1 FROM public.crm_usuarios u WHERE u.user_id=(SELECT auth.uid()))
 );
CREATE POLICY vistoria_teste_insert ON public.vistorias
 FOR INSERT TO authenticated WITH CHECK (
   EXISTS (SELECT 1 FROM public.crm_usuarios u WHERE u.user_id=(SELECT auth.uid()))
 );
CREATE POLICY vistoria_teste_update ON public.vistorias
 FOR UPDATE TO authenticated USING (
   EXISTS (SELECT 1 FROM public.crm_usuarios u WHERE u.user_id=(SELECT auth.uid()))
 ) WITH CHECK (
   EXISTS (SELECT 1 FROM public.crm_usuarios u WHERE u.user_id=(SELECT auth.uid()))
 );
-- Nenhuma política de DELETE: exclusão bloqueada nesta fase.
-- Para fotos, criar bucket privado e políticas de storage.objects
-- separadamente ANTES de testar upload/download.
